+    fn handle_visual_key(&mut self, key: UiKey) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => self.clear_visual_selection(),
+            UiKey::Char('v') => self.start_visual_selection(VisualKind::Character),
+            UiKey::Char('V') => self.start_visual_selection(VisualKind::Line),
+            UiKey::Char(CTRL_V_KEY) => self.start_visual_selection(VisualKind::Block),
+            UiKey::Char('y') => self.yank_visual_selection(None),
+            UiKey::Char('Y') => self.yank_visual_selection(Some(VisualKind::Line)),
+            UiKey::Char('h') | UiKey::Left => self.move_visual_cursor(0, -1),
+            UiKey::Char('j') | UiKey::Down => self.move_visual_cursor(1, 0),
+            UiKey::Char('k') | UiKey::Up => self.move_visual_cursor(-1, 0),
+            UiKey::Char('l') | UiKey::Right => self.move_visual_cursor(0, 1),
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn start_visual_selection(&mut self, kind: VisualKind) {
+        let pane = self.focus;
+        let cursor = self.current_visual_position(pane);
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            kind,
+            anchor: cursor,
+            cursor,
+        });
+        self.mode = UiMode::Command;
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn current_visual_position(&self, pane: PaneFocus) -> TextPosition {
+        let lines = self.selection_pane_lines(pane);
+        let line = match pane {
+            PaneFocus::Left => self.control_selected,
+            PaneFocus::Right => lines.len().saturating_sub(1),
+        }
+        .min(lines.len().saturating_sub(1));
+        let column = lines
+            .get(line)
+            .map(|line| line_char_count(line).saturating_sub(1))
+            .unwrap_or(0)
+            .min(0);
+        TextPosition { line, column }
+    }
+
+    fn move_visual_cursor(&mut self, line_delta: isize, column_delta: isize) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.selection_pane_lines(selection.pane);
+        if lines.is_empty() {
+            return;
+        }
+        let next_line = (selection.cursor.line as isize + line_delta)
+            .clamp(0, lines.len().saturating_sub(1) as isize) as usize;
+        let current_column = selection.cursor.column as isize;
+        let next_column = current_column.saturating_add(column_delta).max(0) as usize;
+        let max_column = lines
+            .get(next_line)
+            .map(|line| line_char_count(line).saturating_sub(1))
+            .unwrap_or(0);
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.cursor = TextPosition {
+                line: next_line,
+                column: next_column.min(max_column),
+            };
+        }
+    }
+
+    fn yank_current_line(&mut self) {
+        let pane = self.focus;
+        let lines = self.selection_pane_lines(pane);
+        let position = self.current_visual_position(pane);
+        if let Some(line) = lines.get(position.line) {
+            self.store_clipboard(line.clone());
+        }
+    }
+
+    fn yank_visual_selection(&mut self, kind_override: Option<VisualKind>) {
+        if let Some(text) = self.visual_selection_text(kind_override) {
+            self.store_clipboard(text);
+        }
+        self.clear_visual_selection();
+    }
+
+    fn store_clipboard(&mut self, text: String) {
+        self.clipboard = text.clone();
+        *self.pending_clipboard.borrow_mut() = Some(text);
+        self.show_status_notice("copied selection", Duration::from_secs(STATUS_NOTICE_SECONDS));
+    }
+
+    fn visual_selection_text(&self, kind_override: Option<VisualKind>) -> Option<String> {
+        let selection = self.visual_selection?;
+        let lines = self.selection_pane_lines(selection.pane);
+        Some(selection_text(
+            &lines,
+            VisualSelection {
+                kind: kind_override.unwrap_or(selection.kind),
+                ..selection
+            },
+        ))
+    }
+
+    fn selection_pane_lines(&self, pane: PaneFocus) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => self.left_pane_text_lines(),
+            PaneFocus::Right => self.last_right_lines.borrow().clone(),
+        }
+    }
+
+    fn left_pane_text_lines(&self) -> Vec<String> {
+        self.left_pane_rows()
+            .into_iter()
+            .map(|row| row.text)
+            .collect()
+    }
+
+    fn left_pane_rows(&self) -> Vec<PaneRow> {
+        let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+        let mut rows = vec![PaneRow {
+            text: if self.control_selected == 0 {
+                "> work-leaf  command".to_string()
+            } else {
+                "  work-leaf  command".to_string()
+            },
+            reversed: false,
+        }];
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            let selected = self.control_selected == visible_position + 1;
+            rows.push(PaneRow {
+                text: compact_agent_row(agent, selected, inner_width),
+                reversed: agent.ready,
+            });
+            if !agent.modified_files.is_empty() {
+                rows.push(PaneRow {
+                    text: format!(
+                        "    files: {}",
+                        agent
+                            .modified_files
+                            .iter()
+                            .map(|path| path.display().to_string())
+                            .collect::<Vec<_>>()
+                            .join(", ")
+                    ),
+                    reversed: false,
+                });
+            }
+            for (label, agents) in [
+                ("conflicts", &agent.conflicting_agents),
+                ("depends-on", &agent.depends_on),
+                ("depended-on-by", &agent.depended_on_by),
+            ] {
+                if !agents.is_empty() {
+                    rows.push(PaneRow {
+                        text: format!(
+                            "    {label}: {}",
+                            agents
+                                .iter()
+                                .map(AgentId::as_str)
+                                .collect::<Vec<_>>()
+                                .join(", ")
+                        ),
+                        reversed: false,
+                    });
+                }
+            }
+        }
+        rows
+    }
+
+    fn selection_spans(&self, pane: PaneFocus, line_index: usize, line: &str) -> Spans<'static> {
+        let Some(selection) = self.visual_selection else {
+            return Spans::from(vec![Span::raw(line.to_string())]);
+        };
+        if selection.pane != pane {
+            return Spans::from(vec![Span::raw(line.to_string())]);
+        }
+        let Some((start, end)) = selection_range_for_line(selection, line_index, line) else {
+            return Spans::from(vec![Span::raw(line.to_string())]);
+        };
+        styled_line_spans(line, start, end)
+    }
+
+    fn replace_last_right_lines(&self, right_content: &str) {
+        *self.last_right_lines.borrow_mut() = split_text_lines(right_content);
+    }
 }
+
+#[derive(Clone, Debug, Eq, PartialEq)]
+struct PaneRow {
+    text: String,
+    reversed: bool,
+}
