struct FakeBackend { state: Arc<Mutex<State>> }
#[derive(Debug)]
struct State { replies: VecDeque<String>, sends: Vec<(AgentId, String)> }
impl FakeBackend {
    fn new() -> Self {
        Self { state: Arc::new(Mutex::new(State { replies: VecDeque::from(["launch reply".to_string(), "status reply".to_string()]), sends: Vec::new() })) }
